	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/organizations/{org_id}/projects/{project_id}/members", wrapper.ListProjectMembers)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/organizations/{org_id}/projects/{project_id}/members/{membership_id}", wrapper.RemoveProjectMember)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/organizations/{org_id}/projects/{project_id}/members/{membership_id}", wrapper.AddProjectMember)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/organizations/{org_id}/projects/{project_id}/cover", wrapper.RemoveProjectCover)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/organizations/{org_id}/projects/{project_id}/cover", wrapper.SetProjectCover)
