// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// PurgeOrgData Delete everything this service keeps for an org, and count what is left (the organization service only)
	// (DELETE /v1/internal/organizations/{org_id}/data)
	PurgeOrgData(ctx context.Context, request PurgeOrgDataRequestObject) (PurgeOrgDataResponseObject, error)
	// ExportOrgData Everything this service keeps for an org, for its export (the organization service only)
	// (GET /v1/internal/organizations/{org_id}/data)
	ExportOrgData(ctx context.Context, request ExportOrgDataRequestObject) (ExportOrgDataResponseObject, error)
	// ForgetMembershipData Delete what this service keeps personally under one membership, for account deletion (the organization and user services only)
	// (DELETE /v1/internal/organizations/{org_id}/memberships/{membership_id}/data)
	ForgetMembershipData(ctx context.Context, request ForgetMembershipDataRequestObject) (ForgetMembershipDataResponseObject, error)
	// GetOnboardingStep Whether this product's onboarding step is done for an org (the organization service only)
	// (GET /v1/internal/organizations/{org_id}/onboarding/{step_id})
	GetOnboardingStep(ctx context.Context, request GetOnboardingStepRequestObject) (GetOnboardingStepResponseObject, error)
	// ExportUserData What this service keeps about one person, for their own export (the organization service only)
	// (GET /v1/internal/users/{user_id}/data)
	ExportUserData(ctx context.Context, request ExportUserDataRequestObject) (ExportUserDataResponseObject, error)
	// ListProjects The organization's projects, newest first
	// (GET /v1/organizations/{org_id}/projects)
	ListProjects(ctx context.Context, request ListProjectsRequestObject) (ListProjectsResponseObject, error)
	// CreateProject Create a project (the projects permission)
	// (POST /v1/organizations/{org_id}/projects)
	CreateProject(ctx context.Context, request CreateProjectRequestObject) (CreateProjectResponseObject, error)
	// DeleteProject Delete a project, its members and its cover (the projects permission)
	// (DELETE /v1/organizations/{org_id}/projects/{project_id})
	DeleteProject(ctx context.Context, request DeleteProjectRequestObject) (DeleteProjectResponseObject, error)
	// GetProject One project
	// (GET /v1/organizations/{org_id}/projects/{project_id})
	GetProject(ctx context.Context, request GetProjectRequestObject) (GetProjectResponseObject, error)
	// UpdateProject Rename a project or change its description (the projects permission)
	// (PATCH /v1/organizations/{org_id}/projects/{project_id})
	UpdateProject(ctx context.Context, request UpdateProjectRequestObject) (UpdateProjectResponseObject, error)
	// RemoveProjectCover Remove the cover image (the projects permission)
	// (DELETE /v1/organizations/{org_id}/projects/{project_id}/cover)
	RemoveProjectCover(ctx context.Context, request RemoveProjectCoverRequestObject) (RemoveProjectCoverResponseObject, error)
	// SetProjectCover Start uploading a new cover image (the projects permission)
	// (POST /v1/organizations/{org_id}/projects/{project_id}/cover)
	SetProjectCover(ctx context.Context, request SetProjectCoverRequestObject) (SetProjectCoverResponseObject, error)
	// ListProjectMembers The memberships a project is shared with, in the order they were added
	// (GET /v1/organizations/{org_id}/projects/{project_id}/members)
	ListProjectMembers(ctx context.Context, request ListProjectMembersRequestObject) (ListProjectMembersResponseObject, error)
	// RemoveProjectMember Stop sharing a project with a member (the projects permission)
	// (DELETE /v1/organizations/{org_id}/projects/{project_id}/members/{membership_id})
	RemoveProjectMember(ctx context.Context, request RemoveProjectMemberRequestObject) (RemoveProjectMemberResponseObject, error)
	// AddProjectMember Share a project with an active member of the organization (the projects permission)
	// (PUT /v1/organizations/{org_id}/projects/{project_id}/members/{membership_id})
	AddProjectMember(ctx context.Context, request AddProjectMemberRequestObject) (AddProjectMemberResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

